   594  armor_parse_headers(pgp_source_t *src)
   595  {
   596      pgp_source_armored_param_t *param = (pgp_source_armored_param_t *) src->param;
   597      char                        header[1024] = {0};
   598
   599      do {
   600          size_t hdrlen = 0;
   601          if (!src_peek_line(param->readsrc, header, sizeof(header), &hdrlen)) {
   602              /* if line is too long let's cut it to the reasonable size */
   603              src_skip(param->readsrc, hdrlen);
   604              if ((hdrlen != sizeof(header) - 1) || !armor_skip_line(param->readsrc)) {
   605                  RNP_LOG("failed to peek line: unexpected end of data");
   606                  return false;
