   988  static bool
   989  cleartext_parse_headers(pgp_source_t *src)
   990  {
   991      pgp_source_signed_param_t *param = (pgp_source_signed_param_t *) src->param;
   992      char                       hdr[1024] = {0};
   993      char *                     hval;
   994      pgp_hash_alg_t             halg;
   995      size_t                     hdrlen;
   996
   997      do {
   998          if (!src_peek_line(param->readsrc, hdr, sizeof(hdr), &hdrlen)) {
   999              RNP_LOG("failed to peek line");
  1000              return false;
  1001          }
  1002
  1003          if (!hdrlen) {
  1004              break;
  1005          }
  1006
  1007          if (strncmp(hdr, ST_HEADER_HASH, 6) == 0) {
  1008              hval = hdr + 6;
  1009
  1010              std::string remainder = hval;
  1011
  1012              const std::string        delimiters = ", \t";
  1013              std::vector<std::string> tokens;
  1014
  1015              tokenize(remainder, delimiters, tokens);
  1016
  1017              for (const auto &token : tokens) {
  1018                  if ((halg = pgp_str_to_hash_alg(token.c_str())) == PGP_HASH_UNKNOWN) {
  1019                      RNP_LOG("unknown halg: %s", token.c_str());
  1020                  }
  1021                  pgp_hash_list_add(param->hashes, halg);
  1022              }
  1023          } else {
  1024              RNP_LOG("unknown header '%s'", hdr);
  1025          }
  1026
  1027          src_skip(param->readsrc, hdrlen);
  1028
  1029          if (!src_skip_eol(param->readsrc)) {
  1030              return false;
  1031          }
  1032      } while (1);
  1033
  1034      /* we have exactly one empty line after the headers */
  1035      return src_skip_eol(param->readsrc);
  1036  }
